```tsx
import { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('[ErrorBoundary]', error, info.componentStack);
    this.props.onError?.(error, info);
  }

  retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.retry);

    return (
      <div role="alert" style={{ padding: '1rem', border: '1px solid #f87171', borderRadius: 6 }}>
        <strong>Something went wrong</strong>
        <pre style={{ margin: '0.5rem 0', fontSize: '0.8em', opacity: 0.8 }}>
          {error.message}
        </pre>
        <button onClick={this.retry}>Retry</button>
      </div>
    );
  }
}
```

**Usage:**
```tsx
// Default fallback
<ErrorBoundary onError={(err, info) => sendToSentry(err, info)}>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary fallback={(err, retry) => (
  <div>
    <p>Oops: {err.message}</p>
    <button onClick={retry}>Try again</button>
  </div>
)}>
  <MyComponent />
</ErrorBoundary>
```

Key points: `getDerivedStateFromError` triggers the fallback render; `componentDidCatch` logs to console + optional `onError` hook (for Sentry etc.); retry clears error state, re-mounting children.
